t 'fix-dot-path-found' 'via-path
~0' 'mkdir -p fdpp; echo '\''echo via-path'\'' > fdpp/fdp2.sh; PATH="$PWD/fdpp:$PATH"; . fdp2.sh'
echo "sh-posix: $((pass + fail)) cases, $pass passed, $fail failed"
cd /
[ $fail = 0 ]
